package kz.nur.home;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.print.*;import android.view.*;import java.io.*;import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity {
 WebView web; ValueCallback<Uri[]> chooser; String pending="";
 @Override public void onCreate(Bundle b){super.onCreate(b);web=new WebView(this);setContentView(web);web.setBackgroundColor(0xff161616);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(true);web.getSettings().setAllowContentAccess(true);web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !"file".equals(r.getUrl().getScheme());}});web.addJavascriptInterface(new Bridge(),"NuRAndroid");web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> c,FileChooserParams p){if(chooser!=null)chooser.onReceiveValue(null);chooser=c;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,11);return true;}});web.loadUrl("file:///android_asset/index.html");}
 public class Bridge {@JavascriptInterface public void save(String name,String data){runOnUiThread(()->{pending=data;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType(name.endsWith(".csv")?"text/csv":"application/json");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,12);});} @JavascriptInterface public void print(){runOnUiThread(()->{PrintManager p=(PrintManager)getSystemService(PRINT_SERVICE);p.print("NuR HOME 3D",web.createPrintDocumentAdapter("NuR HOME 3D"),new PrintAttributes.Builder().build());});}}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==11&&chooser!=null){chooser.onReceiveValue(c==RESULT_OK&&d!=null?new Uri[]{d.getData()}:null);chooser=null;}if(r==12&&c==RESULT_OK&&d!=null){try(OutputStream o=getContentResolver().openOutputStream(d.getData())){o.write(pending.getBytes(StandardCharsets.UTF_8));android.widget.Toast.makeText(this,"Сохранено",0).show();}catch(Exception e){android.widget.Toast.makeText(this,"Ошибка сохранения",1).show();}}}
}
